BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷83·晋少帝本纪·开运元年闰十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b20c86dd55e2fffd503cfcda0a449be32dd9edc8/content/books/zizhi-tongjian/vol-284/year-0944/part-06/sources/library/jiuwudaishi-083-944-leap/source.txt", "note": "《旧五代史》卷83·晋少帝本纪·开运元年闰十二月，段落 jiu-wudaishi-205deb4a7860-p002017；卷界、年界与传主已按上下文校核，纸本及异文待核。", "id": "06a26564-eefe-50a9-8589-a9ae2efe2f86"}, {"title": "资治通鉴·卷284·开运元年闰十二月与次年正月（945年正文不在本批处理）", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b20c86dd55e2fffd503cfcda0a449be32dd9edc8/content/books/zizhi-tongjian/vol-284/year-0944/part-06/sources/library/tongjian-284-944-leap/source.txt", "note": "《资治通鉴》卷284·开运元年闰十二月与次年正月（945年正文不在本批处理），段落 zizhi-tongjian-a63549944a71-p003377；卷界、年界与传主已按上下文校核，纸本及异文待核。", "id": "6c89c878-71a7-571d-b57f-302fc312b6e5"}, {"title": "新五代史·卷62·南唐世家·保大二年闽乱与攻建州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b20c86dd55e2fffd503cfcda0a449be32dd9edc8/content/books/zizhi-tongjian/vol-284/year-0944/part-06/sources/library/xinwudaishi-062-min-campaign/source.txt", "note": "《新五代史》卷62·南唐世家·保大二年闽乱与攻建州，段落 xin-wudaishi-b08f244b9241-p003141；卷界、年界与传主已按上下文校核，纸本及异文待核。", "id": "34d65449-472f-5f0f-9f16-f936571d7693"}, {"title": "资治通鉴·后晋纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cfe7117a41b196f8984cd77f8ab5e4ebfe68ddf8/content/books/zizhi-tongjian/vol-284/year-0944/part-04/sources/library/tongjian-284-944-august-november/source.txt", "note": "《资治通鉴》后晋纪五，段落 zizhi-tongjian-a63549944a71-p003376；电子底本待考，分段待核", "id": "7b81686a-069d-5e08-b61f-fd92146983f9"}, {"title": "新五代史·卷六十八", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/33c4505fd076635fd33c0ce1412ecfa289823f13/content/books/zizhi-tongjian/vol-284/year-0944/part-02/sources/library/xinwudaishi-068-zhu-wenjin/source.txt", "note": "《新五代史》卷六十八，段落 xin-wudaishi-b08f244b9241-p003413；EPUB电子本，纸本及异文待核", "id": "d890caa3-5bdd-5371-a027-7e2322c23458"}, {"title": "新五代史·卷51·杨光远传·青州围城与被杀", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/efabcfd3ab189a0761611575565bd16b0de54ae2/content/books/zizhi-tongjian/vol-284/year-0944/part-05/sources/library/xinwudaishi-051-yang-surrender/source.txt", "note": "《新五代史》卷51·杨光远传·青州围城与被杀，段落 xin-wudaishi-b08f244b9241-p002017；已核卷号、上下文与传主，EPUB电子本，纸本及异文待核。", "id": "0b876564-193b-5205-b71e-182779274d89"}, {"title": "宋史·卷483·陈洪进传·赴建州与任职", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/efabcfd3ab189a0761611575565bd16b0de54ae2/content/books/zizhi-tongjian/vol-284/year-0944/part-05/sources/library/songshi-483-chen-hongjin-mission/source.txt", "note": "《宋史》卷483·陈洪进传·赴建州与任职，段落 songshi-9c6e46fee832-p075238；已核卷号、上下文与传主，EPUB电子本，纸本及异文待核。", "id": "96bd24a5-0966-5c3d-b920-1a3e5698b062"}, {"title": "新五代史·卷九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/76880fa37d0bdb722c1238d971903f0fd476eb32/content/books/zizhi-tongjian/vol-283/year-0944/part-01/sources/library/xinwudaishi-009-944-january/source.txt", "note": "《新五代史》卷九，段落 xin-wudaishi-b08f244b9241-p000335；EPUB电子本，纸本及异文待核", "id": "71c7fc99-919d-58e5-acc1-c401819fcdc4"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱文进", "aliases": ["硃文进", "朱文進", "硃文進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "永泰人，闽国拱宸军将领。《资治通鉴》记他与连重遇多次受王继鹏侮辱而心怀不满，《新五代史》还记二人因宸卫军待遇优厚而激怒部众。生卒年未载。", "biography": null, "status": "draft", "id": "309ef83c-46fe-51a1-86cc-c2cb8dc48d82"}, {"name": "林守谅", "aliases": ["林守諒"], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "朱文进的统军使。944年奉命与李廷锷率军攻泉州，被留从效击败后斩杀。出生年本段未载。", "biography": null, "status": "draft", "id": "74c92e2d-7efa-593b-b552-b416774c388b"}, {"name": "李廷锷", "aliases": ["李廷鍔"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朱文进的内客省使。944年与林守谅率军攻泉州，战败后被留从效俘虏，之后结局本段未载。", "biography": null, "status": "draft", "id": "827095ef-51c3-5060-981c-8dcf70063a5c"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "杜进", "aliases": ["杜進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国大将军。944年王延政派他率两万兵救泉州。与此前驻长溪的卢进名字不同，缺少同人证据，分别建档。生卒年本段未载。", "biography": null, "status": "draft", "id": "1b418f83-62de-5543-bd2a-4d3ea5df5e1b"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "吴成义", "aliases": ["吳成義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国统军使。944年闽国政变后受王延政命率兵讨伐朱文进，未能攻克。后续福建战事尚随主书继续录入。生卒年未载。", "biography": null, "status": "draft", "id": "5b79c091-612f-5d81-9f36-da75ba08386b"}, {"name": "臧循", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 944, "description": "南唐翰林待诏，与查文徽同乡，曾经商而熟悉福建山川。向查文徽提出攻建州方案，随后在邵武被殷军俘获，押至建州斩杀。早年经历具体年月未载。", "biography": null, "status": "draft", "id": "b1b93c37-66c6-5dbd-930a-b4f3ee1189c7"}, {"name": "查文徽", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "休宁人，南唐官员。943年李璟即位后，史书记他与陈觉、冯延巳、冯延鲁、魏岑互相引荐，不久与魏岑同任枢密副使。当时五人被称为五鬼，称呼按史书记载保留。生卒年尚未核。", "biography": null, "status": "draft", "id": "b0abcb8a-3aa7-5d58-8f3c-79f4fc15b117"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "张汉真", "aliases": ["張漢真"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "殷国将领。944年从镛州率八千兵将到建阳一带，查文徽获知后退回建阳。与泉州军将张汉思没有同人证据，不合并。生卒年本段未载。", "biography": null, "status": "draft", "id": "493e276e-e7f9-5930-a601-616b5d065516"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "何延祚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋客省副使。《新五代史》记李守贞派他到杨光远私宅，他命一名未具名都将杀杨光远。与此前被杀的白延祚分开。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "d9426724-cb5b-53cf-813a-22d50ecf3ead"}, {"name": "杨承贵", "aliases": ["楊承貴", "杨承勋", "楊承勛", "楊承勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远之子。940年受父亲派遣围范延光私宅，逼其自尽，随后把范延光推入河中。《新五代史》相关执行者写杨承勋，姓名异说未裁定，不自动合并。生卒年未载。", "biography": null, "status": "draft", "id": "daf29c5e-0a0a-5cc1-aa88-e64404212a3c"}, {"name": "杨承信", "aliases": ["楊承信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。《资治通鉴》称他为次子，938年五月与杨承祚同获优厚任官，具体官名未载。", "biography": null, "status": "draft", "id": "70bde002-fc6d-5293-9fb1-214458b656a6"}, {"name": "杨承祚", "aliases": ["楊承祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的儿子。938年五月被任命为左威卫将军，并与石敬瑭的女儿长安公主结婚。", "biography": null, "status": "draft", "id": "2af4e0bd-ddb5-5c72-b4f6-8e3394d31c7d"}, {"name": "张万迪", "aliases": ["張萬迪"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张万迪，指挥使、率骑转投者。", "biography": null, "status": "draft", "id": "7a521823-c981-5922-b7c3-7c6d39969935"}, {"name": "杨麟（杨光远判官）", "aliases": ["楊麟（楊光遠判官）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "杨光远的节度判官。944年青州归降时奉杨光远命向后晋递交请死表。与903年已录同名人缺少连续身份依据，暂分档保留待核。生卒年本段未载。", "biography": null, "status": "draft", "id": "8312b0a7-e97b-5e5f-a3a5-e225be5f8d11"}, {"name": "任邈", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "青州掌书记。944年闰十二月乙酉因杨光远叛乱被判流放原州，诏令规定以后遇赦也不得放还。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "0bab65b8-fdeb-5b12-bda0-d22e29a46684"}, {"name": "徐晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "青州支使。944年闰十二月乙酉因杨光远叛乱被判流放武州，诏令规定以后遇赦也不得放还。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "e86e177b-e142-5556-abf6-c40f025d8c4c"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "翟光邺", "aliases": ["翟光鄴", "翟光業", "翟光业"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：翟光邺，受遣察安的皇城使。", "biography": null, "status": "draft", "id": "4b6400da-2b69-5857-b364-3106a40c1d45"}, {"name": "李光准", "aliases": ["李光準"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国翰林学士、吏部侍郎。942年十二月任中书侍郎兼户部尚书、同平章事。史书回顾他在酒宴中醉酒触怒王延羲，被下令处死，但官吏未执行，次日又恢复职位。生卒年未载。", "biography": null, "status": "draft", "id": "3147c4c7-55fe-53ad-8887-8354e082b567"}, {"name": "林仁翰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "福州南廊承旨。944年闰十二月丁酉率部反对连重遇与朱文进，杀连重遇后号召众人杀朱文进。《新五代史》称他为裨将。生卒年本段未载。", "biography": null, "status": "draft", "id": "b422146c-60a6-5f7b-ba8e-b77da41f898d"}, {"name": "连重遇", "aliases": ["連重遇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "光山人，闽国控鹤军将领。939年率拱宸、控鹤军起兵攻击王继鹏，拥立王延羲。生卒年未载。", "biography": null, "status": "draft", "id": "5f02df46-1b50-5419-8220-ef50fe37c3eb"}, {"name": "陈洪进", "aliases": ["陳洪進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州副兵马使，主书称临淮，《宋史》记泉州仙游人，地名表述对应关系待核。944年将黄绍颇首级送建州，以说辞突破尤溪阻兵，获王延政任官。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "2fa634eb-359d-513d-8ba2-8168587d3cb7"}, {"name": "赵延寿", "aliases": ["趙延壽", "延寿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：赵延寿，公主丈夫。", "biography": null, "status": "draft", "id": "bf502cd0-4cbb-52e5-b93a-e30caa907a58"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "张从恩", "aliases": ["張從恩"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，曾任澶州防御使。939年正月任后晋枢密副使。生卒年未载。", "biography": null, "status": "draft", "id": "e1e909ad-c88c-54a5-941c-6116c704a870"}, {"name": "马全节", "aliases": ["馬全節"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：马全节，金州防御使、以私财给军并拒战者。", "biography": null, "status": "draft", "id": "bb5608d9-eabe-58ce-8c56-b07e57faadb5"}, {"name": "安审琦", "aliases": ["安審琦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：安审琦，彰圣都指挥使、领顺化节度使者。", "biography": null, "status": "draft", "id": "a579a6a1-65a5-5c8a-9c6c-be178cb049aa"}, {"name": "赵在礼", "aliases": ["趙在禮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：赵在礼。", "biography": null, "status": "draft", "id": "90ff68a5-70f2-5182-8802-93859bae2990"}]'::jsonb)
